<?php declare(strict_types=1); require_once __DIR__.'/includes/bootstrap.php'; require_once __DIR__.'/includes/ensure_courses.php'; require_once __DIR__.'/includes/catalog.php'; require_once __DIR__.'/includes/media.php'; $lh_page_title='Courses';$lh_description='Explore practical SmartToolz Learning Hub courses for computer skills, programming, AI, web development, SEO and career skills.';$rows=[];$categories=[];try{$rows=$db->query("SELECT c.*,lc.name category_name,lc.slug category_slug,lc.icon category_icon,(SELECT COUNT(*) FROM learning_lessons l WHERE l.enabled=1 AND ((l.course_id=c.id) OR EXISTS(SELECT 1 FROM learning_chapters ch WHERE ch.id=l.chapter_id AND ch.course_id=c.id))) lesson_count FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.enabled=1 ORDER BY c.featured DESC,c.id DESC")->fetchAll(PDO::FETCH_ASSOC);$categories=$db->query("SELECT slug,name,icon FROM learning_categories WHERE enabled=1 ORDER BY sort_order,name")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log($e->getMessage());}$category=trim((string)($_GET['category']??''));if($category!=='')$rows=array_values(array_filter($rows,fn($r)=>($r['category_slug']??'')===$category));include __DIR__.'/includes/header.php';include __DIR__.'/includes/navbar.php';?><div class="container-fluid"><div class="row"><div class="col-lg-3 col-xl-2 p-0"><?php include __DIR__.'/includes/sidebar.php';?></div><main class="col-lg-9 col-xl-10 py-4 py-lg-5"><div class="container-fluid"><section class="lh-hero p-4 p-md-5 mb-4"><div class="row align-items-center g-4"><div class="col-xl-8"><span class="badge text-bg-primary mb-3">SmartToolz Learning Hub</span><h1 class="display-5 fw-bold lh-course-title mb-3">Learn practical skills. Build real projects.</h1><p class="lead text-secondary mb-4">Structured courses for computer skills, web development, programming, AI and digital work.</p><form action="/learning-hub/search.php" method="get" class="row g-2"><div class="col-md-9"><input class="form-control form-control-lg" name="q" placeholder="Search courses, tutorials and lessons…" aria-label="Search Learning Hub"></div><div class="col-md-3"><button class="btn btn-primary btn-lg w-100" type="submit"><i class="bi bi-search me-1"></i>Search</button></div></form></div><div class="col-xl-4"><div class="lh-card overflow-hidden"><img src="/learning-hub/assets/images/courses/web.svg" class="w-100 lh-course-hero-img" width="3840" height="2160" alt="SmartToolz Learning Hub technology learning" loading="eager"><div class="p-4"><div class="d-flex align-items-center gap-3"><div class="lh-brand-mark"><i class="bi bi-mortarboard-fill"></i></div><div><div class="fw-bold">Start learning today</div><div class="small text-secondary"><?=number_format(count($rows))?> courses · <?=number_format(array_sum(array_map(fn($r)=>(int)$r['lesson_count'],$rows)))?> lessons</div></div></div></div></div></div></div></section><div class="d-flex flex-wrap gap-2 mb-4"><a class="btn btn-sm lh-filter-pill <?= $category===''?'active':''?>" href="/learning-hub/courses.php">All courses</a><?php foreach($categories as $cat):?><a class="btn btn-sm lh-filter-pill <?=$category===$cat['slug']?'active':''?>" href="/learning-hub/courses.php?category=<?=rawurlencode($cat['slug'])?>"><?=lh_h($cat['icon']??'📚')?> <?=lh_h($cat['name'])?></a><?php endforeach;?></div><div class="d-flex justify-content-between align-items-end mb-3"><div><h2 class="h3 fw-bold mb-1"><?= $category!==''? 'Courses in '.lh_h($rows[0]['category_name']??ucwords(str_replace('-',' ',$category))):'Explore courses' ?></h2><p class="text-secondary mb-0">Choose a course and learn at your own pace.</p></div></div><div class="row g-4"><?php foreach($rows as $c):?><div class="col-md-6 col-xl-4"><a class="lh-card d-flex flex-column h-100 overflow-hidden text-decoration-none text-dark" href="/learning-hub/course.php?slug=<?=rawurlencode($c['slug'])?>"><div class="position-relative"><img src="<?=lh_h(lh_course_image((string)($c['category_slug']??'')))?>" class="w-100 lh-course-img" width="3840" height="2160" alt="<?=lh_h($c['title'])?> course artwork" loading="lazy"><?php if((int)$c['featured']===1):?><span class="badge text-bg-light border text-primary position-absolute top-0 end-0 m-3">Featured</span><?php endif;?></div><div class="p-4 d-flex flex-column flex-grow-1"><div class="small text-primary fw-semibold"><?=lh_h($c['category_name']??'Learning Hub')?></div><h3 class="h5 fw-bold mt-1 mb-2 lh-course-title"><?=lh_h($c['title'])?></h3><p class="small text-secondary mb-4"><?=lh_h($c['description']??'Practical step-by-step learning with exercises and projects.')?></p><div class="mt-auto d-flex flex-wrap gap-2"><span class="badge text-bg-light border"><?=lh_h($c['level']??'Beginner')?></span><span class="badge text-bg-light border"><?=number_format((int)$c['lesson_count'])?> lessons</span></div><div class="small fw-semibold text-primary mt-3">Start course <i class="bi bi-arrow-right"></i></div></div></a></div><?php endforeach;if(!$rows):?><div class="col-12"><div class="lh-empty p-5 text-center"><div class="fs-1 mb-2">📚</div><h3 class="h5">No courses found</h3><p class="text-secondary mb-3">Try another category or browse all courses.</p><a class="btn btn-primary" href="/learning-hub/courses.php">View all courses</a></div></div><?php endif;?></div><div class="lh-ad-slot my-5">Advertisement</div></div></main></div></div><?php include __DIR__.'/includes/footer.php';?><script src="/learning-hub/assets/js/app.js"></script><script src="/learning-hub/assets/js/router.js"></script>